require __DIR__ . '/app/bootstrap.php';require_once __DIR__ . '/app/Badge.php';Auth::requireLogin();$pdo=Database::connection();ensure_member_soft_delete_schema($pdo);ensure_badge_schema($pdo);$id=(int)($_GET['id']??0);$mode=(string)($_GET['mode']??'view');
try{$member=badge_member_data($pdo,$id);$template=badge_pick_template($pdo,$member);if(!$template)throw new RuntimeException('Er is nog geen actieve algemene of taggebonden lidkaart-template ingesteld.');$layout=badge_layout($template);}catch(Throwable $e){http_response_code(404);exit('Lidkaart kan niet worden gemaakt: '.e($e->getMessage()));}
$data=['full_name'=>$member['full_name'],'first_name'=>$member['first_name'],'last_name'=>$member['last_name'],'member_number'=>$member['member_number']??'','photo'=>$member['photo_path']??'','member_type'=>$member['member_type_label'],'status'=>$member['status_label'],'member_since'=>$member['member_since']??'','birth_date'=>$member['birth_date']??'','email'=>$member['email']??'','mobile'=>$member['mobile']??'','address'=>$member['address']??'','postal_city'=>$member['postal_city'],'weight_kg'=>($member['weight_kg']??'')!==''?((string)$member['weight_kg'].' kg'):'','tags'=>$member['tags'],'payment_status'=>$member['payment_status_label'],'free_flight_entitled'=>$member['free_flight_entitled_label'],'free_flight_date'=>$member['free_flight_date']??''];
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lidkaart <?=e($member['full_name'])?></title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0;background:#e8ebef}.toolbar{display:flex;justify-content:center;gap:10px;padding:14px}.btn{padding:10px 14px;border:0;border-radius:9px;background:#111;color:#fff;text-decoration:none;cursor:pointer;font-weight:700}.secondary{background:#fff;color:#111}.wrap{display:flex;justify-content:center;padding:18px}.badge{position:relative;width:86mm;height:54mm;background:#fff;overflow:hidden;box-shadow:0 8px 28px #0004}.badge #bg{position:absolute;inset:0;width:100%;height:100%}.field{position:absolute;display:flex;align-items:center;overflow:hidden;line-height:1.05;white-space:nowrap}.code{padding:0!important}.qrbox>div,.qrbox canvas,.qrbox img{width:100%!important;height:100%!important;display:block!important}.barcode svg{width:100%;height:100%;display:block}.photoField{justify-content:center;align-items:center}.photoField img{width:100%;height:100%;object-fit:contain;object-position:center;display:block}@page{size:86mm 54mm;margin:0}@media print{html,body{width:86mm;height:54mm;background:#fff}.toolbar{display:none}.wrap{padding:0}.badge{box-shadow:none}}</style></head><body><div class="toolbar"><button class="btn" id="printBtn">Print lidkaart</button><button class="btn" id="downloadBtn">Download Badge PDF</button><a class="btn secondary" href="/member.php?id=<?=$id?>">← Lidfiche</a></div><div class="wrap"><div class="badge" id="badge"><canvas id="bg"></canvas></div></div>
